              <span>{testResult.message}</span>
            </p>
          ) : null}
        </div>
        <div className="flex shrink-0 items-center gap-1">
          <button
            type="button"
            aria-label={`Test ${secret.key_name}`}
            disabled={validateVaultSecret.isPending}
